def extract_code(reply: str) -> str:
    """从模型回答里提取纯 Python 代码。
    优先提取 ```python ... ``` 代码块；没有代码块则从首个 def/from/import
    开头的行开始截取到结尾；都没有则返回原文。
    """
    start_tag = "```python"
    start = reply.find(start_tag)
    if start != -1:
        code_start = start + len(start_tag)
        while code_start < len(reply) and reply[code_start] in " \t\r\n":
            code_start += 1
        code_end = reply.find("```", code_start)
        if code_end != -1:
            return reply[code_start:code_end].strip()

    lines = reply.splitlines(keepends=True)
    for index, line in enumerate(lines):
        first_part = line.lstrip().split(None, 1)
        if first_part and first_part[0] in {"def", "from", "import"}:
            return "".join(lines[index:]).strip()

    return reply

